-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ruRU" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.mage.fire.Name"] = "Огонь"
L["rm.era.mage.fire.Description"] = "Огонь с 10 по 60 уровень; выбирается, когда у вас есть очки в «Огне» и ни одного во «Льду» или когда «Огонь» — ваша основная ветка. Начало боя: Огненная глыба (иначе Огненный шар); Огненная глыба после Присутствия разума; Ожог поддерживает пять наложений Уязвимости к огню при Улучшенном ожоге на целях, которые проживут достаточно долго; Огненный взрыв и Ожог добивают; Огненный шар заполняет. Три и более врага в бою: Взрывная волна, Огненный столб, Чародейский взрыв, Конус холода, Снежная буря. Напоминания: Возгорание при пяти наложениях Ожога против элитных противников и в долгих боях, доспех, Чародейский интеллект, самоцветы маны, Ледяная преграда, Щит маны, Прилив сил, Антимагия, Снятие малого проклятия, Ледяная глыба, Присутствие разума. По умолчанию выключено: вплетение Огненного взрыва всякий раз, когда он готов."
L["rm.era.mage.fire.warcrafttavern.Name"] = "Огонь (Warcraft Tavern)"
L["rm.era.mage.fire.warcrafttavern.Description"] = "Огонь по Warcraft Tavern — альтернатива рекомендуемой встроенной ротации «Огонь», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Возгорание тратится в начале боя против элитных противников и боссов, а не ждёт наложений Ожога; начало боя: Огненная глыба; Ожог поддерживает пять наложений при Улучшенном ожоге; Огненный шар заполняет; Огненный взрыв — только в движении. Группы врагов: сначала Огненный столб, затем Чародейский взрыв, Конус холода и Взрывная волна вблизи, Снежная буря на расстоянии. Те же напоминания, что и в рекомендуемой встроенной ротации «Огонь»."
L["rm.era.mage.frost.Name"] = "Лед"
L["rm.era.mage.frost.Description"] = "Лед с 1 по 60 уровень, также для билдов «Тайной магии» и ротация мага по умолчанию до выбора талантов. Ледяная стрела (до 4 уровня — Огненный шар); Кольцо льда, когда противник добирается до вас, кроме рейдовых боссов; Чародейские снаряды, как только противник добрался до вас, если у вас есть Улучшенный чародейский снаряд; Конус холода, Чародейский взрыв и Снежная буря, когда с вами сражаются три и более врага; Огненный взрыв в движении при лишней мане; Огненный взрыв и жезл добивают обычных противников в одиночной игре; жезл, когда мана кончилась. Напоминания: доспех (Ледяной доспех в одиночной игре, Магический доспех в группе, никогда не заменяя выбранный вами), Чародейский интеллект, сотворение и использование самоцветов маны, Ледяная преграда, Щит маны, Прилив сил, Антимагия, Снятие малого проклятия, Ледяная глыба, Холодная хватка, Мощь тайной магии и Присутствие разума. По умолчанию выключены: Огненный столб при Обледенении и Ледяная стрела 1-го ранга для наложения Зимней стужи. Скачок, Превращение, удержание врагов на расстоянии и выбор цели остаются за вами."
L["rm.era.mage.frost.icyveins.Name"] = "Лед, AoE-прокачка (Icy Veins)"
L["rm.era.mage.frost.icyveins.Description"] = "Прокачка со Снежной бурей по руководству Icy Veins по AoE-прокачке; выбирается автоматически, когда вы играете в одиночку с Улучшенной снежной бурей. От двух врагов в бою: Кольцо льда на группу, Конус холода, пока Кольцо восстанавливается, Снежная буря, как только рядом с вами никого нет, Чародейский взрыв, когда враги рядом; Ледяная стрела по одиночной цели, Огненный взрыв и жезл для добивания. Щит маны и Ледяная преграда ставятся перед каждым боем. Сбор группы врагов, Скачок и удержание врагов на расстоянии остаются за вами."
L["rm.forever.mage.arcane.Name"] = "Тайная магия"
L["rm.forever.mage.arcane.Description"] = "Тайная магия, когда «Тайная магия» — ваша основная ветка талантов с 11 очками и вы знаете Чародейскую вспышку. Начинает бой Ледяной стрелой в одиночной игре или Чародейской вспышкой в группе; затем Чародейские снаряды при Заградительных стрелах, Чародейская вспышка при Ясности мысли, Чародейский гнев при трёх наложениях Чародейской вспышки, Чародейская вспышка до четырёх наложений на элитных противниках и до двух на прочих целях, пока хватает маны (в Forever мана скрыта), затем Стрела ледяного огня, Ледяная стрела или Огненный шар, чтобы вызвать Заградительные стрелы, и жезл в одиночной игре, когда не хватает маны на заклинание. Без Чародейского гнева (старый вариант из беты) наложения тратит Огненный взрыв. В движении: Огненный взрыв. Если с вами сражаются три и более врага: Чародейский взрыв. Напоминания: Присутствие разума и Мощь тайной магии против элитных противников (Мощь тайной магии больше не ждёт, пока у вас останется половина маны), а также общие напоминания мага о поддержании эффектов."
L["rm.forever.mage.fire.Name"] = "Огонь"
L["rm.forever.mage.fire.Description"] = "Огонь, когда «Огонь» — ваша основная ветка талантов с 11 очками (уровень Огненной глыбы). Начинает бой Огненной глыбой против элитных противников, иначе Стрелой ледяного огня или Огненным шаром; затем Огненная глыба при трёх наложениях Разогрева, Ледяное копье при Ледяных пальцах или по замороженной цели (гибриды «Огня» и «Льда»), Огненный взрыв по готовности, Ожог для поддержания ваших пяти наложений Уязвимости к огню на элитных противниках, Стрела ледяного огня (с 40 уровня) или Огненный шар, жезл в одиночной игре, когда не хватает маны на заклинание. В движении: Огненный взрыв или Ледяное копье. Если с вами сражаются четыре и более врага: Огненный столб, Взрывная волна, Чародейский взрыв. Ожог начинает накопление наложений, только когда у вас есть Улучшенный ожог; Ожог вблизи выключен, пока вы его не включите. Напоминания: Возгорание и Присутствие разума против элитных противников, а также общие напоминания мага о поддержании эффектов."
L["rm.forever.mage.fire.icyveins.Name"] = "Огонь, прокачка (Icy Veins)"
L["rm.forever.mage.fire.icyveins.Description"] = "Билд прокачки «Огня» по Icy Veins без Улучшенного ожога — альтернатива рекомендуемой встроенной ротации «Огонь», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Начинает бой Огненной глыбой, использует Огненный взрыв, чтобы потратить Огненный след, Ожог, пока противник приближается (в Forever здоровье цели скрыто, поэтому добивание слабых целей — за вами), затем Стрелу ледяного огня (с 40 уровня) или Огненный шар. Те же AoE, движение, жезл и напоминания, что и во встроенной ротации «Огонь», но без Возгорания и Присутствия разума."
L["rm.forever.mage.frost.Name"] = "Лед"
L["rm.forever.mage.frost.Description"] = "Лед с 1 по 60 уровень; также ротация мага по умолчанию в Forever до заклинаний из талантов (Огненный шар, пока на 4 уровне не появится Ледяная стрела). Начинает бой Ледяной стрелой; затем Ледяное копье при Ледяных пальцах или по замороженной цели (в том числе пока ещё применяется Ледяная стрела — чтобы прервать её или выпустить вместе с ней), Конус холода при пяти наложениях Зимней стужи, Чародейские снаряды при Заградительных стрелах, Ледяная стрела и жезл в одиночной игре, когда на Ледяную стрелу не хватает маны. В движении: Ледяное копье, иначе Огненный взрыв. Если с вами сражаются три и более врага: Конус холода; пять и более: Снежная буря или Чародейский взрыв, если противник бьёт вас. AoE от Warcraft Tavern с Огненным столбом и Чародейским взрывом есть в ротации, но выключено. Напоминания: Чародейский интеллект, доспех (Ледяной или Морозный в одиночной игре, Магический в группе; выбранный вами доспех никогда не заменяется), Ледяная преграда, Антимагия, Снятие малого проклятия, Кольцо льда, когда противник добирается до вас, Холодная хватка. В Forever здоровье и мана скрыты от аддонов, поэтому добивание слабых целей Огненным взрывом, Прилив сил и Ледяная глыба остаются за вами; Скачок, кайт, Превращение и самоцветы маны тоже остаются за вами."
L["rm.mop.mage.arcane.Name"] = "Рекомендуемая"
L["rm.mop.mage.arcane.Description"] = "Рекомендуется для «Тайной магии» с 10 по 90 уровень (выбирается при специализации «Тайная магия»). Чародейская вспышка набирает четыре Чародейских заряда; при четырёх срабатывание «Чародейские стрелы!» тратится на Стрелы, а без него Чародейский обстрел применяется, как только мана падает ниже 90%. При мане выше 95% ротация продолжает применять Вспышку — так играет симулятор. Стрелы никогда не копятся на двух срабатываниях, Обстрел применяется до того, как Путешествие во времени вернёт вас назад, а против двух и более врагов Обстрел применяется на каждых четырёх зарядах; Конус холода и Чародейский взрыв, когда рядом пять врагов. Поддерживает вашу бомбу из талантов, а в движении без Плавучей льдины — Огненный взрыв или Ледяное копье. Напоминания: Мощь тайной магии и Путешествие во времени при четырёх зарядах и срабатывании, Морозный доспех (до 54 уровня — Раскаленный), Чародейская гениальность, Антимагия, Самоцвет маны, Зеркальное изображение, Ледяная преграда, Плавучая льдина, Руна мощи или Чародейство. Искажение времени, Чарокрад и Величие разума выключены; Руну мощи по-прежнему нужно ставить вручную."
L["rm.mop.mage.arcane.icyveins.Name"] = "Обстрел при четырёх зарядах (Icy Veins)"
L["rm.mop.mage.arcane.icyveins.Description"] = "Правило «Тайной магии» из руководств (Icy Veins, Wowhead, Method, wowtbc.gg) — альтернатива рекомендуемой встроенной ротации «Тайная магия»: при четырёх Чародейских зарядах — Чародейские стрелы, если есть срабатывание, иначе Чародейский обстрел, сколько бы у вас ни было маны; Стрелы — только при четырёх зарядах. Всё остальное (Путешествие во времени, бомбы, AoE, движение, напоминания) — как в рекомендуемой ротации, за исключением того, что Мощь тайной магии предлагается при четырёх зарядах, не дожидаясь срабатывания. По умолчанию выключена: включите её и выключите рекомендуемую встроенную ротацию «Тайная магия» или повысьте её приоритет."
L["rm.mop.mage.fire.Name"] = "Рекомендуемая"
L["rm.mop.mage.fire.Description"] = "Рекомендуется для «Огня» с 10 по 90 уровень (выбирается при специализации «Огонь»). Начинает бой Огненной глыбой с полным временем применения, затем Пламенный взрыв (до 24 уровня — Огненный взрыв) превращает Разогрев в срабатывание «Огненная глыба!», которое применяется сразу, если только Возгорание не вот-вот восстановится; затем ротация ждёт следующего Разогрева, пока вы применяете Огненный шар. Возгорание применяется сразу после Огненной глыбы, пока на цели висят Воспламенение и горение от Огненной глыбы; аддон не видит силу Воспламенения, поэтому о слабом судите сами. Поддерживает вашу бомбу из талантов, распространяет эффекты Пламенным взрывом, когда с вами сражаются два и более врага, Конус холода и Чародейский взрыв против пяти врагов рядом, Ожог в движении. Напоминания: Раскаленный доспех, Величие разума, Путешествие во времени при обоих срабатываниях, Самоцвет маны, Чародейская гениальность, Антимагия, Зеркальное изображение, Ледяная преграда, Плавучая льдина, Чародейство или Руна мощи. Дыхание дракона, Искажение времени и Чарокрад выключены."
L["rm.mop.mage.fire.icyveins.Name"] = "Придерживать «Огненную глыбу!» (Icy Veins)"
L["rm.mop.mage.fire.icyveins.Description"] = "Игра за «Огонь» по Icy Veins, Method и wowtbc.gg — альтернатива рекомендуемой встроенной ротации «Огонь»: срабатывание «Огненная глыба!» придерживается, пока к нему не добавится Разогрев, затем применяется вместе с вашим Огненным шаром, а в одиночку тратится, только когда вот-вот истечёт. Всё остальное — как в рекомендуемой ротации. По умолчанию выключена: включите её и выключите рекомендуемую встроенную ротацию «Огонь» или повысьте её приоритет."
L["rm.mop.mage.frost.Name"] = "Рекомендуемая"
L["rm.mop.mage.frost.Description"] = "«Лед» с 10 по 90 уровень (выбирается при специализации «Лед»). Ледяное копье при двух Ледяных пальцах, Стрела ледяного огня при Заморозке мозгов, ваша бомба из талантов, Ледяной шар, Ледяное копье при одних Ледяных пальцах, Ледяная стрела; с 87 уровня срабатывание придерживается для Путешествия во времени, если до него меньше 10 секунд. Против двух и более врагов: Ледяной шар, Конус холода и Чародейский взрыв, когда они рядом, Снежная буря, когда четверо стоят на месте. В движении без Плавучей льдины — Ледяное копье и Огненный взрыв. Напоминания: элементаль воды, Холод против всех, кроме босса (ставите сами), Стылая кровь в связке с Путешествием во времени, Путешествие во времени при двух Ледяных пальцах во время Стылой крови, Морозный доспех (до 54 уровня — Раскаленный), Самоцвет маны, Чародейская гениальность, Антимагия, Зеркальное изображение, Ледяная преграда, Плавучая льдина, Чародейство или Руна мощи. Холодная хватка, Величие разума, Искажение времени и Чарокрад выключены."
L["rm.mop.mage.unspecialized.Name"] = "До выбора специализации"
L["rm.mop.mage.unspecialized.Description"] = "Для уровней 1–9 и любого мага, который ещё не выбрал специализацию. Стрела ледяного огня, Огненный взрыв для добивания цели или в движении, Ледяное копье в движении, как только изучено, Чародейский взрыв, когда в зоне ближнего боя три и более врага. Напоминания: Кольцо льда, когда противник добирается до вас, Антимагия, а также Раскаленный доспех и Чародейская гениальность, если вы до них дошли. Выбор специализации на 10 уровне переключает на встроенную ротацию этой специализации."
L["rm.retail.mage.arcane.Name"] = "Боевой помощник Blizzard"
L["rm.retail.mage.arcane.Description"] = "Рекомендуется для специализации «Тайная магия». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — напоминания о том, что Боевой помощник оставляет вам: Чародейский выброс в бою, Чародейский интеллект вне боя, Антимагия против прерываемого заклинания, Призматический барьер по готовности в бою и ваша расовая способность в бою. В бою заклинания противников скрыты, поэтому Антимагия загорается только там, где игра их показывает; на Retail здоровье скрыто, поэтому Ледяная глыба и другие экстренные кнопки — на ваше усмотрение. За вами остаются: Зеркальное изображение, Манипуляции со временем, Скачок и аксессуары."
L["rm.retail.mage.arcane.guide.Name"] = "Для справки (Icy Veins и SimulationCraft)"
L["rm.retail.mage.arcane.guide.Description"] = "Только для справки, по умолчанию выключена: приоритет «Тайной магии» по руководствам. Чародейский залп и Ясность мысли скрыты от аддонов в бою в Midnight (видны только чародейские заряды), поэтому этот список не может там работать; мана на Retail скрыта, поэтому Прилив сил при низкой мане остаётся за вами; читайте его или продублируйте, чтобы поэкспериментировать. Начало боя: Чародейская вспышка. Ярость солнца: Чародейские стрелы при Ясности мысли и менее чем 12 наложениях Залпа, Призматическая стрела вне Чародейской души, Чародейский обстрел при четырёх зарядах вместе с 12 наложениями Залпа и Ясностью мысли или с 25 наложениями Залпа, либо во время Чародейской души при любом числе зарядов, Призматическая стрела, Чародейский шар при менее чем трёх зарядах, Чародейский импульс против трёх врагов или без зарядов, Чародейская вспышка. Чаромет (известны Околдованные обломки): Призматическая стрела, Шар против групп врагов, Обстрел при 20 наложениях Залпа (против двух и более врагов — только при четырёх зарядах), Стрелы при Ясности мысли и менее чем 15 наложениях Залпа, Шар и Импульс при менее чем трёх зарядах (без Импульса во время Чародейского выброса), Чародейская вспышка. Чародейский обстрел, когда Вспышку применить нельзя. Напоминания: Чародейский выброс, Касание мага после Обстрела или Призматической стрелы во время Выброса или задолго до него, Величие разума без зарядов после Обстрела, а также напоминания встроенной ротации с Боевым помощником."
L["rm.retail.mage.fire.Name"] = "Боевой помощник Blizzard"
L["rm.retail.mage.fire.Description"] = "Рекомендуется для специализации «Огонь». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — напоминания о том, что Боевой помощник оставляет вам: Возгорание в бою, Чародейский интеллект вне боя, Антимагия против прерываемого заклинания, Пылающая преграда по готовности в бою и ваша расовая способность в бою. В бою заклинания противников скрыты, поэтому Антимагия загорается только там, где игра их показывает; на Retail здоровье скрыто, поэтому Ледяная глыба и другие экстренные кнопки — на ваше усмотрение."
L["rm.retail.mage.fire.guide.Name"] = "Для справки (Icy Veins, Wowhead и SimulationCraft)"
L["rm.retail.mage.fire.guide.Description"] = "Только для справки, по умолчанию выключена: приоритет «Огня» по руководствам. Полоса везения, Разогрев, Пироклазм и заряды Огненного взрыва скрыты в бою в Midnight, поэтому ротация не может там работать. Огненный взрыв в конце применения заклинания, чтобы превратить Разогрев в Полосу везения; начало боя: Огненная глыба. Огненная глыба (Огненный столб против четырёх и более врагов) при Гипертермии, Метеор, Огненная глыба при Полосе везения, Огненный взрыв при Разогреве во время Возгорания, Огненная глыба при Пироклазме, Ожог при Дрожащем воздухе или в движении, Огненный взрыв при Разогреве, затем Стрела ледяного огня или Огненный шар. Напоминания: Возгорание в конце применения заклинания с временем применения, Пылающая преграда и вспомогательные напоминания. Ожидание Поджигателя и приурочивание Метеора к Возгоранию остаются за вами."
L["rm.retail.mage.frost.Name"] = "Боевой помощник Blizzard"
L["rm.retail.mage.frost.Description"] = "Рекомендуется для специализации «Лед». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — напоминания о том, что Боевой помощник оставляет вам: Призыв элементаля воды, если у вас есть этот талант, а элементаля нет, Чародейский интеллект вне боя, Антимагия против прерываемого заклинания, Ледяная преграда по готовности в бою и ваша расовая способность в бою. В бою заклинания противников скрыты, поэтому Антимагия загорается только там, где игра их показывает; на Retail здоровье скрыто, поэтому Ледяная глыба и другие экстренные кнопки — на ваше усмотрение."
L["rm.retail.mage.frost.guide.Name"] = "Для справки (Icy Veins и SimulationCraft)"
L["rm.retail.mage.frost.guide.Description"] = "Только для справки, по умолчанию выключена: приоритет «Льда» по руководствам для каждой ветки героических талантов. Срабатывания, наложения Замерзания и восстановление способностей скрыты в бою в Midnight, поэтому ротация не может там работать. Начало боя: Стрела ледяного огня или Ледяная стрела. Ледяной огонь (известна Стрела ледяного огня): Ледовый шип по готовности, Кометная буря против одного или двух врагов, Шквал при Заморозке мозгов без Ледяной Бездны, Ледяное копье при двух зарядах Ледяных пальцев, Морозный луч, Ледяной шар, Снежная буря при Леденящем дожде против трёх врагов, Ледяное копье при Ледяных пальцах с Ледяной Бездной или при двенадцати наложениях Замерзания, Шквал, Кольцо обледенения или Конус холода против пяти, затем Ледовый шип или Стрела ледяного огня. Чаромет: Кометная буря, Шквал при Заморозке мозгов, Ледяное копье при двух зарядах Пальцев, Ледяной шар, Ледовый шип по готовности, Снежная буря при Леденящем дожде, Ледяное копье при Ледяных пальцах или шести наложениях Замерзания, Морозный луч, Шквал, Кольцо обледенения или Конус холода против четырёх, Снежная буря против семи, затем Ледовый шип или Ледяная стрела. Ледяное копье в движении. Напоминания: Призыв элементаля воды, Ледяная преграда и вспомогательные напоминания."
L["rm.retail.mage.initial.Name"] = "Боевой помощник Blizzard"
L["rm.retail.mage.initial.Description"] = "Рекомендуется до выбора специализации (пока игра сообщает начальную специализацию мага). Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — общие напоминания всех встроенных ротаций мага, каждое — как только вы знаете соответствующее заклинание. Когда на 10 уровне вы выбираете специализацию, её встроенные ротации вступают в силу."
L["rm.sod.mage.arcane.Name"] = "Тайная магия (SoD)"
L["rm.sod.mage.arcane.Description"] = "Урон «Тайной магии» для сезона открытий; выбирается, когда «Тайная магия» — ваша основная ветка и выгравирована Чародейская вспышка. Чародейские снаряды при Заградительных стрелах; Чародейский обстрел при четырёх наложениях Чародейской вспышки; Стрела гибельного огня, когда это безопасно, но никогда при четырёх и более наложениях Гибельного огня; Живой жар по готовности; Чародейская вспышка заполняет. Чародейский обстрел и Огненный взрыв в движении; Живой жар и Чародейский взрыв против групп врагов. Напоминания: Мощь тайной магии против элитных противников и в долгих боях, Присутствие разума вместе с Мощью тайной магии или в движении, Стылая кровь, Холодная хватка и прочие напоминания мага."
L["rm.sod.mage.fire.Name"] = "Огонь (SoD)"
L["rm.sod.mage.fire.Description"] = "Огонь для сезона открытий с 1 по 60 уровень; там же — ротация мага по умолчанию. Использует выгравированные вами руны: Огненная глыба при Пути огня сразу; Живая бомба поддерживается на целях, которые проживут достаточно долго; Ожог при Улучшенном ожоге, пока у Уязвимости к огню меньше двух наложений или она вот-вот спадёт; Живой жар по готовности; Стрела гибельного огня при пяти наложениях Уязвимости к огню, но никогда при четырёх и более наложениях Гибельного огня (пятое вас убьёт); Стрела ледяного огня, иначе Огненный шар. Живая бомба, Живой жар и Огненный взрыв в движении; Живой жар, Живая бомба, Взрывная волна, Конус холода, Огненный столб и Снежная буря против групп врагов. Напоминания: Огненный взрыв при Перегреве, Возгорание, Стылая кровь и Холодная хватка, Раскаленный или другой доспех, Чародейский интеллект, самоцветы маны, Ледяная преграда, Щит маны, Прилив сил, Антимагия, снятие проклятий, Ледяная глыба. Распространение Живой бомбы по целям остаётся за вами."
L["rm.sod.mage.frost.Name"] = "Лед (SoD)"
L["rm.sod.mage.frost.Description"] = "Лед для сезона открытий с 10 уровня; выбирается, когда «Лед» — ваша основная ветка. Ледяные пальцы уходят в Ледяное копье при трёх и более ваших наложениях Вымораживания, иначе в Глубокую заморозку; Стрела гибельного огня при срабатывании Заморозки мозгов, а в остальных случаях — когда это безопасно, но никогда при четырёх и более наложениях Гибельного огня; Живая бомба и Живой жар, если выгравированы; Стрела чар льда, иначе Стрела ледяного огня, иначе Ледяная стрела. Ледяное копье, Ледяной шар, Живая бомба и Огненный взрыв в движении; Ледяной шар, Живой жар, Живая бомба, Снежная буря и Конус холода против групп врагов. Напоминания: Ледяной шар, Стылая кровь, Холодная хватка, доспех, самоцветы маны и прочие напоминания мага. Постановка заклинания в очередь в момент попадания стрелы остаётся за вами."
L["rm.sod.mage.frost.warcrafttavern.Name"] = "Лед, руны огня (SoD, Warcraft Tavern)"
L["rm.sod.mage.frost.warcrafttavern.Description"] = "Билд «Льда» на рунах огня из 4-й фазы по Warcraft Tavern — альтернатива рекомендуемой встроенной ротации «Лед» для сезона открытий, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Начало боя: Огненная глыба; Огненная глыба при Пути огня; Живая бомба поддерживается; Ожог до пяти наложений при Улучшенном ожоге; Стрела гибельного огня — только при срабатывании Заморозки мозгов и никогда при четырёх и более наложениях Гибельного огня; Стрела ледяного огня заполняет. Живая бомба и Огненный взрыв в движении; Живая бомба, Конус холода и Снежная буря против групп врагов. Напоминания: Огненный взрыв при Перегреве, Ледяной шар во время Стылой крови, Стылая кровь, Холодная хватка и прочие напоминания мага."
L["rm.sod.mage.healer.Name"] = "Лекарь (SoD)"
L["rm.sod.mage.healer.Description"] = "Лечение магом в сезоне открытий; выбирается, когда выгравирована Регенерация или Массовая регенерация. С дружественной целью: Перемотка времени и Темпоральное спасение при здоровье ниже половины, Регенерация, когда нет вашего Темпорального маяка, Массовая регенерация, Временная аномалия. С враждебной целью — урон, который лечит цели ваших маяков: Стрела чар льда для лекарей «Льда», иначе Чародейские снаряды при Заградительных стрелах, Чародейский обстрел при двух наложениях Чародейской вспышки, Стрела гибельного огня, когда это безопасно (никогда при четырёх и более наложениях Гибельного огня), и Чародейская вспышка. Напоминания: Мощь тайной магии, Присутствие разума, Ледяной шар и прочие напоминания мага. По умолчанию выключены: Чародейский взрыв против групп врагов, а также Ледяное копье и Глубокая заморозка для лекарей «Льда». Пока вы поддерживаете Массовую регенерацию, следующее заклинание уже показано, поэтому её можно сразу отменить (её прямое лечение невелико). Кого лечить, остаётся за вами."
L["rm.tbc.mage.arcane.Name"] = "Тайная магия"
L["rm.tbc.mage.arcane.Description"] = "Тайная магия; выбирается, когда «Тайная магия» — ваша основная ветка талантов. До 64 уровня: Чародейские стрелы, а при нехватке маны — Ледяная стрела. С 64 уровня: Чародейская вспышка во время разгона (Мощь тайной магии, Кровожадность или мана выше 35%), иначе три наложения Чародейской вспышки и Ледяная стрела, пока наложения не начнут спадать. Чародейский взрыв и Конус холода при трёх и более врагах. Среди напоминаний — Мощь тайной магии, Присутствие разума, самоцвет маны и Прилив сил."
L["rm.tbc.mage.fire.icyveins.Name"] = "Огонь (Icy Veins)"
L["rm.tbc.mage.fire.icyveins.Description"] = "Огонь по Icy Veins; выбирается, когда «Огонь» — ваша основная ветка талантов. Огненная глыба начинает бой, как только изучена, Улучшенный ожог поддерживает пять наложений Уязвимости к огню, Огненный шар — основное заклинание, Огненный взрыв — в движении; Взрывная волна, Дыхание дракона и Огненный столб — при трёх и более врагах. Напоминания: Раскаленный, Магический или Ледяной доспех, Возгорание при здоровье цели ниже 20%, самоцвет маны, Прилив сил и общие вспомогательные заклинания мага."
L["rm.tbc.mage.fire.wowhead.Name"] = "Огонь (Wowhead)"
L["rm.tbc.mage.fire.wowhead.Description"] = "«Огонь» по Wowhead и симулятор. Как встроенная ротация «Огонь» от Icy Veins, но вплетает Огненный взрыв всякий раз, когда он готов, пока вы стоите на месте (больше урона, больше расход маны), и начинает бой с Огненного шара вместо Огненной глыбы. Альтернатива рекомендуемой встроенной ротации «Огонь» от Icy Veins, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет."
L["rm.tbc.mage.frost.Name"] = "Лед"
L["rm.tbc.mage.frost.Description"] = "Лед с 1 по 70 уровень; также ротация мага по умолчанию до выбора талантов. Ледяная стрела (до 4 уровня — Огненный шар), Кольцо льда, когда вас кто-то бьёт, Конус холода со Снежной бурей или Чародейским взрывом, когда с вами сражаются три и более врага, Ледяное копье по замороженным целям и в движении, жезл, когда кончилась мана. Напоминания: доспех, Чародейский интеллект, самоцвет маны, Прилив сил, Антимагия, Чарокрад, Ледяная преграда, Стылая кровь, Холодная хватка и элементаль воды. Скачок, Ледяная глыба, кайт и выбор цели остаются за вами."
